function lpx(wx){ return LP.cx + wx * LP.r; }
function lpy(wy){ return LP.cy - wy * LP.r; }

var gLeft = draw.group();
var gRight = draw.group();
var gLabels = draw.group();

function arcD(cx, cy, r, a1, a2){
  var x1=cx+r*Math.cos(a1), y1=cy-r*Math.sin(a1);
  var x2=cx+r*Math.cos(a2), y2=cy-r*Math.sin(a2);
  var large=Math.abs(a2-a1)>Math.PI?1:0;
  var sweep=a2>a1?0:1;
  return 'M '+x1+' '+y1+' A '+r+' '+r+' 0 '+large+' '+sweep+' '+x2+' '+y2;
}
function sectorD(cx, cy, r, a1, a2){
  var x1=cx+r*Math.cos(a1), y1=cy-r*Math.sin(a1);
  var x2=cx+r*Math.cos(a2), y2=cy-r*Math.sin(a2);
  var large=Math.abs(a2-a1)>Math.PI?1:0;
  var sweep=a2>a1?0:1;
  return 'M '+cx+' '+cy+' L '+x1+' '+y1+' A '+r+' '+r+' 0 '+large+' '+sweep+' '+x2+' '+y2+' Z';
}
function braceH(g, x1, x2, y, depth){
  var mx=(x1+x2)/2;
  g.path('M '+x1+' '+y+' C '+x1+' '+(y+depth*0.6)+', '+((x1+mx)/2)+' '+(y+depth*0.6)+', '+mx+' '+(y+depth)+' C '+((mx+x2)/2)+' '+(y+depth*0.6)+', '+x2+' '+(y+depth*0.6)+', '+x2+' '+y)
    .fill('none').stroke({color:'#000',width:1.2});
}
function braceV(g, x, y1, y2, depth){
  var my=(y1+y2)/2;
  g.path('M '+x+' '+y1+' C '+(x+depth*0.6)+' '+y1+', '+(x+depth*0.6)+' '+((y1+my)/2)+', '+(x+depth)+' '+my+' C '+(x+depth*0.6)+' '+((my+y2)/2)+', '+(x+depth*0.6)+' '+y2+', '+x+' '+y2)
