    }
    // Caption
    lbl.text('Area of triangle').font({family:'serif',size:14}).attr({x:ox+S/2-55,y:oy+42}).fill('#000');
    // Fraction sin x / 2
    drawFraction(lbl, ox+S/2, oy+62, 'sin x', '2', dimmed);
  }
}

function drawFraction(lbl, cx, cy, num, den, dimmed){
  var col = dimmed ? 'rgba(0,0,0,0.15)' : '#000';
  lbl.text(num).font({family:'serif',style:'italic',size:14}).attr({x:cx-14,y:cy}).fill(col);
  lbl.line(cx-18,cy+4,cx+18,cy+4).stroke({color:col,width:1});
  lbl.text(den).font({family:'serif',size:14}).attr({x:cx-4,y:cy+20}).fill(col);
}

function drawAll(){
  gLeft.clear(); gRight.clear(); gLabels.clear();
  drawLeftPanel();
  drawRightPanel();
}

// UI handlers
function update_angleX(v){
  state.angleX=v;
  drawAll();
}
function toggle_viewMode(on){
  state.viewMode=on?'overlay':'side';
  drawAll();
}
function trigger_highlightRegion(){
  highlightIdx=(highlightIdx+1)%highlightStates.length;
  state.highlight=highlightStates[highlightIdx];
  document.getElementById('highlightBtn').textContent='Highlight: '+state.highlight;
  drawAll();
}

